import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response, NextFunction } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const upload = multer({ 
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'application/pdf') {
      cb(null, true);
    } else {
      cb(new Error('Only PDF files are allowed'));
    }
  }
});

export const uploadMiddleware = upload.single('resume');

export async function parseResumePdf(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    if (!req.file) {
      res.status(400.json({ error: 'No resume file uploaded' }));
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    req.body.parsedText = pdfData.text;
    next();
  } catch (error) {
    res.status(500).json({ error: 'Failed to parse PDF document text' });
  }
}

export interface MatchResult {
  score: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  keywordFrequencies: Record<string, number>;
}

export function calculateResumeMatch(resumeText: string, jobDescription: string): MatchResult {
  const cleanText = (text: string) => text.toLowerCase().replace(/[^\w\s]/g, '').split(/\s+/);

  const jdWords = Array.from(new Set(cleanText(jobDescription)));
  const resumeWords = cleanText(resumeText);

  const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'with', 'an', 'by']);
  const relevantJdWords = jdWords.filter(word => word.length > 2 && !stopWords.has(word));

  const resumeWordSet = new Set(resumeWords);
  const matchedKeywords: string[] = [];
  const missingKeywords: string[] = [];
  const keywordFrequencies: Record<string, number> = {};

  resumeWords.forEach(word => {
    keywordFrequencies[word] = (keywordFrequencies[word] || 0) + 1;
  });

  relevantJdWords.forEach(word => {
    if (resumeWordSet.has(word)) {
      matchedKeywords.push(word);
    } else {
      missingKeywords.push(word);
    }
  });

  const score = relevantJdWords.length > 0 
    ? Math.round((matchedKeywords.length / relevantJdWords.length) * 100) 
    : 0;

  return {
    score,
    matchedKeywords,
    missingKeywords,
    keywordFrequencies
  };
}
